INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (1, '2022-xzf', '2022年国家公务员考试申论试题（行政执法卷）', 2022, '行政执法类', 5);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (1, 1, '材料1', '新型冠状病毒肺炎疫情发生后，党中央、国务院出台了一系列支持企业发展的惠企政策。N市积极落实各项惠企政策，不断优化营商环境，推动区域经济高质量跨越式发展。
“当时举步维艰，那笔钱可真是雪中送炭啊。”宏远环保科技公司石经理现在回想起来，仍然有些感慨。疫情影响下，这家公司资金严重短缺，已经上马的技改项目濒临停滞。2020年7月，该公司通过N市“政策直给直兑”绿色通道申请了两项技改专项补贴和一项专利奖励。“星期一下午申报，星期三钱款就到账了。”高效的办事机制让石经理由衷地为政府点赞。为了积极落实中央的“两直”政策（即资金直达市县基层、直接惠企利民），市政府专门开设绿色通道，提前做好项目储备、底数核查等工作，确保了资金的及时、高效、精准分配，切实为企业纾困解难。
腾飞电缆股份有限公司姚经理也对N市惠企政策的“秒兑”大加赞赏。2021年4月，这家公司意外地收到了一笔12万元的财政专项补贴款。“我们并没有提出申请，会不会是财政误拨？”姚经理专程到市财政局查询，工作人员告诉他，这是市政府新推出的“免申即享”服务，即通过各部门联动、资源整合和信息共享等方式，对符合条件的企业免于申报直接发放奖补资金，享受优惠政策，做到应享尽享、应兑尽兑，切实增强企业的获得感。“他们直接将企业经营数据和奖励政策相匹配，通过后台的数据分析和精准核查发现我们能够享受这个奖励政策，就直接把资金拨过来，真是太振奋人心了！”姚经理说。
在一家大型数据集团，N市惠企政策兑现上门服务座谈会正在进行。市政府有关职能部门的工作人员通过“家访式”上门服务，现场解答这家民营高科技企业在人才引进、商标注册和专利申报等方面所能享受到的10多项政策红利。集团企宣孟总监深受触动：“有些方面的政策我们确实不是很清楚，他们主动告诉我们有哪些惠企政策，我们符合哪些方面的条件，还提醒我们抓紧时间申报，如果说以前是‘人找政策’那么现在就是‘政策找人’。”为切实做好惠企利企工作，N市还成立了“帮办代办服务中心”，由行政审批局组建了一支专业的惠企政策兑现帮办代办工作队伍，让企业少跑腿、好办事、不添堵。
不久前，彗光科技有限公司狄总经理将写着“政企一家亲”的锦旗赠予“亲清家园”。N市依托5G互联网和大数据等新一代信息技术，搭建了“亲清家园”智慧服务平台，推行惠企政策“掌上提、在线批、直达付、全程督”服务模式，让惠企政策直达“准、快、实”。目前，已有经信局、人社局、生态环境局等14个涉企部门入驻“亲清家园”并提交了相关服务清单，开展互动联建活动。一旦发现企业有困难，平台就会根据目录分析所涉及的职能部门，迅速联系相关部门协调解决。
“乌家堡乡动物防检组杨某某等人在服务市场主体时接受宴请、收受礼品……”近日，市纪检监察机关连续通报损害营商环境案例多起，剑指以落实优惠政策之名损害企业利益、敲诈勒索、吃拿卡要等现象，对涉及的党员干部和单位集中曝光。市纪检监察机关以跟进监督、精准监督、全程监督等方式推动惠企政策真正落实，让企业真正定下心、稳住神。“通过‘亲清家园’平台中植入的‘智慧监督’功能，我们督促各部门梳理所有惠企政策，全部上线公开，实现全程无纸化在线申报、审批，对在规定时间内仍未外理的审批人员及时在线上提醒。”市纪检监察机关有关负责人介绍，这种“监督于问题未发之时”的方式，使惠企政策落实更加公正、透明、高效。他还说：“构建亲清政商关系，要求我们的干部既要当好‘店小二’，做到‘亲企’，又要筑牢‘防火墙’，做到‘清己’，有为且有畏。”
老陈是外省一家大型园林工程公司的财务负责人。去年，他们公司在N市承建了小区园林绿化工程。“跨省通办，还能一网通办，在家里点点鼠标就可以完成申报，真是省时省力，这在以前是不敢想象的！”刚办完业务的老陈感慨地说。以往，老陈要带上合同和企业证照到N市有关部门报验登记，再预缴申报增值税和附加税（费），按照18个月的工程周期算，要来回跑10多次。自从N市推出涉税业务全国通办以来，只需登录本地电子税务系统，几分钟即可完成跨省涉税业务办理。目前，N市已经实现了包括发票代开在内的108项政务服务跨省通办，“异地易办”正成为越来越多纳税人、缴费人的共同感受。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (1, 2, '材料2', '没有嘈杂的说话声，没有成群结队等候办事的群众，也没有柜台和窗口，取而代之的是一个咨询导办台和多张电脑桌，帮办员和群众两个一组，并排坐在电脑前办理业务。这是记者在Z县便民中心看到的场景。
市民王女士带着材料前来办理一个餐饮公司的注册登记和食品经营许可证。看到王女士走下电梯，在咨询导办台前值守的导办员小葛马上迎去，问明来意后，小葛将王女士引导至受理服务区的一台电脑前就坐。紧接着帮办员小盛来到王女士旁边与她并排坐下。小盛一边查看材料，一边就有关问题进行交流，登录行政审批系统，录入信息，拍照上传......所有业务在愉快交谈中快速完成。王女士把小盛的一举一动全都看在眼里。“过去我们来办事，都是工作人员在柜台里面，我们在外面，总觉得里面的人高高在上。现在没有了柜台，与工作人员肩并肩坐着，看着整个办事过程，距离拉近了，相互沟通也更方便了。”王女士连连称赞。
小丁是一家企业的员工，受公司负责人委托，来办理营业执照变更。他认为，以前隔着柜台和工作人员沟通，难免交流不畅，现在，“无柜台”的办理模式让办事群众可以在一旁观看每一步操作过程，同时，“无障碍”交流也让一件事情办下来更加轻松和高效。从“面对面”窗口受理到“肩并肩”帮办服务，看似是为民服务中心前台设置形式的一个小变化，背后却蕴含着政府服务理念的转变。“对于新的工作模式，刚开始时大家确实不是很适应，许多人有一定的心理落差，甚至有人抱怨。”为民服务中心的工作人员老冯说。习惯了前来办事人员的笑脸，要真正转变工作观念，确实不是一蹴而就的。
目前Z县便民服务中心在综合受理区设立了25个工位，主要涉及不动产登记、税务、公积金等无差别全科受理事项。这样的变化对于工作人员的业务能力有了更高的要求。以往工作中，工作人员习惯了“铁路警察，各管一段”。改革初始，面对群众的多样化需求，不少受理人员茫然失措，疲于应付，不适应办理无差别全科受理事项。服务中心温主任说，他们第一时间加强了业务培训，特别是对高频事项的答疑、材料审核、系统录入等流程进行重点培训，做到群众“进一门、取一号、找一人、办成事”，但许多事项涉及到不同主管部门的职能分工，沟通协调起来确实不容易，要想真正做到位，必须和行政管理体制改革同步推进。
“我们都知道，去许多地方办事，都要首先取号。那如何能更便捷智能？我们通过对接政务服务2.0取叫号系统，完成取叫号信息，事项目录配置。办事群众可通过‘这里办’APP取号，通过大厅综合屏实时查看取号信息，也可通过手机出示‘云证通’中的二维码，窗口即可扫码，‘无感智办’，实现‘码上办事’。”温主任介绍道。
服务柜台的撤销，消除了办事群众与审批受理人员之间的距离，提升了群众的获得感和满意感。温主任说：“通过打造‘无柜台，肩并肩’的服务新模式，我们希望更多的群众切实享受到改革带来的红利。现在撤掉的是‘眼中的柜台’，但我们更要在撤掉‘心中的柜台’上下功夫。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (1, 3, '材料3', '没想到现在只要网上提交资料就可以现场领票。近日市民小祝顺利拿到了购房发票，这是J市房屋不动产交易登记集成办理平台，开出的首张购房发票。
自开展党史学习教育以来，J市税务局将党史学习教育与税收工作相结合，优化服务办实事，将与群众接触频次高、办理复杂的业务列为办实事的重点项目，打通多部门之间业务壁垒，实行多部门联办，不断推进“以数治税”，构建集成服务应用平台，数据跑路代替了群众跑路，办税缴费服务向智能化、数字化、场景化转变。身在外地的小李最近就感受到了这一转变。今年年初，小李在家乡购买了一套房产，但一直没空回乡办理不动产权证。小李与税务局的“税管家”对接后，经“云税驿站”一站式办理了不动产登记，很快就通过邮政专递拿到了不动产权证，“虽然在网上操作麻烦点，但与专程返回老家相比，还是省事多了。”小李说。
“明天就是征期了，网上申报一直不成功，这可怎么办呢？”税务局工作人员小赵接到一个求助电话，新气象包装有限公司法人巩先生在网上报税时遇到了难题，了解到巩先生在外地且对网上操作不太熟悉后，小赵通过屏幕共享功能，“手把手”协助他在云端办税。“税务人员可以直接看到我的操作界面，这样的辅导方式比自己看操作图解和视频要高效得多。”在小赵的同步指导下，巩先生顺利完成了申报。今年，J市税务局结合“服务怎样我体验，发现问题我整改”专项活动，推出“线上+线下”陪办服务新模式。线上，“云税官”通过云端实时辅导纳税人网上办税；线下，根据纳税人需求和实际状况，对“特殊业务、特殊人群、特殊事件”帮助协调各类涉税事项，让纳税人享受便利。“会不会专项活动结束后就没有这种帮助了？”巩先生有点担心，他希望这一服务模式可以长期延续下去。
J市西部是典型的山区。以往，当地群众在服务延伸点自助办税遇到困难，往往需要电话连线或者到办税服务厅处理，但是存在处理效率低，路途耗时长等问题。对此，当地税务部门依托“互联网+政务服务”资源，为办理基础涉税业务的纳税人提供了具有清晰指引功能的二维码。简单扫一扫，跳出的页面就能将办税所需的关键信息一次性告知纳税人，让纳税人办税时间变得更短、办税渠道变得更宽。对于有些群众，尤其是老年人不会扫码、误操作甚至担心上当受骗等问题，税务部门负责人表示，他们会考虑派人实地巡回指导，进乡入村帮助办理业务。
前不久，J市税务局“春雨润苗”党员服务队走进该市特色小微企业示范园工业区，为园区内新入驻的42家小微企业开展政策辅导。华荣再生资源利用有限公司办税人员小夏开心地说：“国家政策给力，纳税服务到位。有清单、有详情，还有解释，税惠政策在税务干部的梳理和讲解下，让人一目了然！这样的活动如果能定时定期地开展就更好了。”此外，J市税务局还设立了“春雨润苗”便民办税服务热线，抽调党员业务骨干专门负责接听答复，确保纳税人、缴费人涉税电话咨询“打得通”“答得清”“办得好”。
“简明易懂的‘办税指南针’特别实用，只需要按照上面的步骤来操作，很快就能办理完成。”小锦鲤海鲜烧烤大排档的蔡老板分享了他近日的办税体验，“税务部门服务越来越贴心了。很多像我们店一样的个体工商户，规模小，没有条件聘请专业的财务人员。随着办税‘指南针’等有针对性服务举措的推出，我们这些非专业人员办起来也比较高效。不过我听别人说，有些地方的税务局在大厅中引入了第三方服务，可以专门为小规模纳税人提供‘一对一’辅导，我觉得本地税务局也可以借鉴。”');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (1, 4, '材料4', 'S省河西地区是全国最大的蔬菜、花卉外繁制种基地。该地每年大量进口国外原种，繁育成熟后再次出口，是当地农业特色支柱产业。种子进出境检验检疫是当地L海关的重点业务工作之一。
在一片南瓜田里，L海关工作人员小潘和同事手中拿着放大镜，仔细观察一株秧苗。“苗期病虫害监测至关重要，是外来有害生物早发现、早防治的关键环节。这株秧苗叶子打卷、边缘焦黄，受虫害影响严重，需要取样送实验室检测。”两人一边说着，一边迅速取样、封样、登记，整套程序行云流水，专业而娴熟。进境种子可能携带外来有害生物，外来有害生物一旦传入，将对当地农林业生产和生态安全造成不可估量的损失。多年来，L海关不断总结监管经验，形成了科学完备的检疫监管体系，切实为外繁制种产业健康发展保驾护航。“海关人员专业负责，在加强进境原种抽样检测的同时，每年在种子育苗期、生长期分3次开展田间病虫害监测，把病虫害扼杀在初始阶段，这有效避免了病虫害的蔓延。以前就曾出现过在种子出口检疫中发现病虫害而造成重大损失的情况。”东方种子有限公司负责人说。
2021年初，欧洲某国发布了种子进口新规定，对进口种子取样、检测和植物检疫证书提出新要求。“我们公司的种子主要出口该国。新规发布后，公司上下都很紧张。”当地知名企业正红种子有限公司负责人说。L海关反应迅速，主动组织有关专家为企业详细解读新规具体内容，通过深入浅出的讲解和“一对一”指导，帮助企业积极应对，避免了重大损失。“下一步，我们将对国外技术性贸易措施进行跟踪研究和评估，及时提出针对性应对措施和建议，让企业能够有效应对国外技术性贸易措施变化。”海关有关负责人说。
L海关拥有全国唯一的外繁种子检疫国家重点实验室。经过多年的投入、完善和优化，实验室在外繁种子主要病虫害检测技术、除害处理技术和品质检验能力等方面都提供了强有力的技术支撑。L海关技术中心相关负责人表示：“科技在产业发展中的引领作用会更加突出。不久前，中国检验检疫科学研究院与我们海关合作建立了‘种子健康研究中心’。我们将继续加强实验室建设，探索建立外繁制种监管信息化平台，通过大数据比对，提高检测的针对性和检出率，用先进技术护航产业发展。”
去年以来，受多种因素影响，国际航空口岸进境航班大幅减少，造成国外原种“进口难”，严重影响外繁制种企业育种。L海关急企业所急，特事专办，全面分析了进口原种遇到的问题，指导企业多样化选择原种进口方式，针对性地帮助企业解决“引种难”问题。对于暂停航线国家和地区的原种，建议通过相邻国家转关进口，或办理检疫审批手线后，通过国际快递的形式进口原种。同时，积极对接相关部门，为进境种子优先配舱、强化全国“一体化”通关。L海关着力落实种子查验送检“预提离”制度，对于系统布控需进行实验室检测的种子，经收发货人或其代理人提交承诺书，可先行提离，优先保障育种工作顺利开展。今年春季，L海关共计检疫监管进境种子113票，取样送检66票，企业“预提离”65票，有效解决了企业难题。
“以前，我们企业遇到海关非正常办公时间需要办理通关手续的情况，可以向海关申请预约通关，但需要派人到海关现场递交纸本申请材料。自从海关全面推广上线‘预约通关网上办理平台’后，我们足不出户就能提交申请、办结通关手续，这在以前是难以做到的。我们知道，这一切的背后是海关工作人员的辛苦和付出，他们真正做到了‘7×24’预约通关和查验服务。”L海关不断创新检疫监管模式，持续提升通关效率，支持全省外繁种子扩大出口。今年上半年，S省出口种子货值超1.6亿元，有效带动了当地群众增收致富。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (1, 5, '材料5', '21年4月29日《中华人民共和国反食品浪费法》（以下简称反食品浪费法）经第十三届全国人民代表大会常务委员会第二十八次会议通过并颁布实施。5月11日，G市市场监管局向当地一所中学发出《责令改正通知书》，并对当事人进行了约谈，其原因是执法人员发现该中学食堂存在蔬菜过度挑选问题——“蔬菜叶有虫眼或稍微泛黄，能吃却全被当垃圾扔掉”。此外执法人员还给出建议：不太好看但还能吃的食材，可以员工内部消化，或定向捐给一些社会组织，尽量做到物尽其用，不浪费。这被认为是自《反食品浪费法》实施之后，G市市场监管局开出的首张罚单，由此引发了社会热议。
学生家长黎女士：菜叶出现泛黄等情形，实际上不单只是一个品相上“不太好看”的问题，而是食品质量已出现质变的征兆。食堂工作人员扔掉这些蔬菜，是希望学生能吃上更新鲜的蔬菜。孩子在这样的食堂吃才能保证食品安全，我们家长才能放心。这样的良心食堂应该表扬，怎么能罚？
该中学后勤中心主任：对于什么情况下食材可以食用，什么情况下必须丢弃，这个尺度不太好掌握。有虫眼或泛黄菜叶给孩子吃吧，传出去就是“烂菜叶”；不给孩子吃吧，扔了又是“浪费食物”，真是太难了！这是一场食品安全和食品浪费的打架！有时候看着食堂没有卖掉的饭菜被倒掉，确实也觉得可惜，可是什么能捐？捐到哪里？怎么捐？没有规范的捐赠平台和制度，我们也无从下手。
某律师：要科学准确、令人信服地判断扔掉某种食品食材的行为是否属于浪费，相关执法判断标准不宜仅简单凭借执法人员从感官上笼统地判断为“还能吃”，应当进一步拿出更确凿的、具有说服力且更具可操作性的配套执行操作标准。
法学研究会某理事：反食品浪费是全社会的责任，简单来说，做饭者、卖饭者和吃饭者，各方都有责任，也都有义务，其责任主体超过了其他法律，这是《反食品浪费法》的一大特点。当前，由于我国各地的经济发展水平不同，饮食结构、饮食习惯等存在差异，法律不能一刀切地制定一个统一的标准，只能作原则性规定。这就要求地方根据具体情况和实际需要，制定本地反食品浪费的具体办法，要保证立法质量，每一条规定、罚则都要有科学依据，应充分动员社会各方面发表意见，充分吸纳群众的建议。
某大学法学教授：“争议性”执法并不可怕，可怕的是执法者在实际执法过程中，未能真正吃透法律精神，直接“照搬”条文或者其他情况下的执法经验。有的甚至拿法律当标枪，作为政绩宣传冲业绩的工具。这不仅远离了法律制度设置的初衷，更是远离了民意。不希望条分缕析的法律，被当作工具用来上纲上线，而应文以致用，读懂生活，读懂民心。同时，针对复杂多样的社会实际，只有深入具体的生活案例中，法律才有生命。
网民甲：我国每年浪费的食物数量十分惊人。有一项调查表明，某大学食堂倒掉的饭菜占学生购买饭菜总量的28.3%。成由勤俭败由奢，浪费食物不但造成了巨大的经济浪费，而且处理食品垃圾所释放出的气体会产生温室效应，也严重破坏了自然环境。现在，反食品浪费既然有法可依，就应该“零容忍”，这样才能在全社会有效扼杀食品浪费的歪风邪气，形成厉行节俭之风。
网民乙：执法部门的人员给出的建议逻辑有问题。难道内部员工、其他社会组织的人员食品安全标准就可以降格？合理的建议推动执法精确化，不恰当的提议会影响执法的公信力。
网民丙：《反食品浪费法》的出台，是基于我国粮食的供求矛盾，意在解决生活中粮食浪费现象严重的问题。另外，食品生产不能只算经济账，还要算上违法的代价。而且学校本来就是教育人的地方，更应该率先垂范，厉行节约，杜绝浪费，食堂这种行为不利于勤俭节约校风的形成。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (1, 1, '问题一：“给定资料1”反映了N市积极落实惠企政策的有关情况，请简述其主要做法及成效。
要求：全面、准确、有条理。不超过250字。', 15, 250, '做法：一、建立高效的办事机制。提供财政专项补贴，开设绿色通道，推出“免申即享”服务。二、加强政策相关服务。上门解答惠企政策；成立帮办代办服务中心，组建服务队伍。三、搭建智慧服务平台。1、推行线上服务模式，涉企部门入驻平台，协调解决困难；2、植入“智慧监督”功能，全部惠企政策上线公开，实现全程无纸化在线申报审批。四、实现一网通办。涉税业务全国通办，多项服务跨省通办。
成效：构建亲清政商关系；及时、高效、精准分配资金；纾解企业困难，增强获得感；节省企业办理时间，提升效率和服务质量；使惠企政策落实更加公正、透明、高效。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (1, 2, '问题二：根据给定材料2，谈谈“现在撤掉的是‘眼中的柜台’，但我们更要在撤掉‘心中的柜台’上下功夫”这句话的理解。
要求：分析全面，条理清晰，不超过300字。', 15, 300, '政府不仅要打造服务新模式，还要真正转变工作观念，提高服务水平。
一、撤掉“眼中的柜台”指撤销服务柜台，从“面对面”窗口受理到“肩并肩”帮办服务，蕴含着政府服务理念的转变。消除了办事群众与审批受理人员之间的距离，提升群众的获得感和满意度，让办事更加轻松和高效。
二、撤掉“心中的柜台”指转变服务观念态度。由于工作模式的转变，造成员工心理落差，对业务能力也有更高的要求。为此，服务中心加强业务培训，同时对接政务服务叫号系统、手机APP和制作二维码，优化办理流程，达到便捷化、智能化。
但真正转变工作观念并非一蹴而就，所以要继续加强各部门的沟通协调，同步推进行政管理体制改革，让更多群众切实享受到改革红利。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (1, 3, '问题三：J市税务局积极优化税收服务，为群众办实事，采取了多项举措，效果良好，请根据材料3，就J市税务局如何进一步强化举措，巩固成果，形成长效机制，写一份工作建议。
要求：（1）紧扣资料，内容全面；（2）建议具有针对性，可行性；（3）准确简明，条理清晰；（4）不超过500字。', 20, 500, '关于J市巩固税收服务成果的建议书
尊敬的领导：
我市税务局为群众办实事，采取了多项举措，效果良好。为进一步强化举措、巩固成果，形成长效机制，特提出以下建议：
一、推动服务智能化。继续将党史学习教育与税收工作相结合，优化服务办实事，列出重点项目，打通业务壁垒，实行多部门联办，推进“以数治税”，构建集成服务应用平台，转变办税缴费服务智能化、数字化、场景化。
二、创新服务新模式。开展专项活动，常态化推出“线上+线下”陪办服务新模式。线上通过云端实时辅导纳税人办税，线下根据纳税人需求帮助协调各类事项，方便群众。
三、完善告知方式。依托“互联网+政务服务”资源，提供具有指引功能的二维码，并提供实地巡回指导，帮助办理业务。
四、开展党员服务活动。成立党员服务队，为企业开展政策辅导；设立便民办税服务热线，安排业务骨干接听答复，确保电话咨询的有效性。
五、提供针对性指导。针对非专业人员推出“办税指南针”，提供办税操作流程；引入第三方服务，专门为小规模纳税人提供“一对一”指导，提升效率。
XXX
XXXX年XX月XX日');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (1, 4, '问题四：有关部门拟召开一场以“严执法，优服务，促发展”为主题的经验交流会。请根据“给定资料4”，撰写一份关于L海关的工作经验交流材料提纲。
要求：（1）紧扣资料，内容全面；（2）准确简明，条理清晰；（3）不超过500字。', 20, 500, '关于L海关工作经验交流的材料提纲
L海关认真落实严执法、优服务，有力地促进了河西地区农业特色产业发展，主要工作经验有：
一、形成检疫监管体系。加强进境原料抽样检测，通过目测、取样等检测程序，监测苗期病虫害状况，减少外来有害生物入侵风险；分阶段开展田间病虫害监测，避免病虫害蔓延，为外繁制种产业健康发展保驾护航。
二、积极应对贸易变化。组织专家解读新规内容，通过讲解和指导，帮助企业应对困难，避免损失。
三、注重科技引领作用。打造检疫重点实验室，提供技术支撑；建立种子健康研究中心，加强实验室建设，建立外繁制种监管信息化平台，提高检测针对性和检出率。
四、实施针对性帮扶。全面分析进口难题，指导企业多样化选择进口方式；对接相关部门，为进境种子优先配舱，强化全国“一体化”通关，落实种子查验送检“预提离”制度，保障育种工作顺利开展。
五、创新检疫监管模式。推广上线预约办理平台，实行全天候预约通关和查验服务，提升通关效率，支持外繁种子扩大出口。
今后，还将对国外技术性贸易措施进行跟踪研究和评估，及时提出针对性应对措施和建议。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (1, 5, '问题五：《反食品浪费法》实施后，G市市场监管局出具的首张《责令改正通知书》引发了社会热议。请根据材料5，以G市市场监管局的名义写一封公开信，回应社会关切，正确引领舆论，营造良好的执法环境。
要求：（1）观点鲜明，内容全面；（2）逻辑清晰，用语恰当；（3）字数800-1000字。', 30, 1000, '致广大市民朋友的一封公开信
市民朋友们：
近来，我市市场监管局针对某中学食堂存在蔬菜过度挑选的问题，对当事人进行约谈，并开出首张《责令改正通知书》后，食品浪费问题重回大众视野，有人认为是“支持加强管理”，也有人认为这是“矫枉过正”，这引发了社会热议。
这一次的责令整改表明了我市重视食品浪费问题，因为食品浪费不仅造成了巨大的经济浪费，而且处理食品垃圾所释放的气体会加重温室效应，也严重破坏了自然环境，我市对于食品浪费问题“零容忍”。但在这一次的执法过程中确实存在违法行为界定不明确、缺乏相关法律依据、执法操作评判标准不统一、执法者在执法过程中脱离实际等问题。
针对以上问题，我局将从以下几个方面着手改进：
一、反食品浪费做到有法可依。根据《反食品浪费法》，并结合我市具体情况，制定反食品浪费的具体办法，完善具有说服力和可操作性的配套文件和细则，规范并统一食品捐赠平台和制度；广泛发动并采纳社会各方意见。
二、反食品浪费做到优化执法。统一配套执行标准，执法前培训相关人员，提高服务意识；执法过程中杜绝形式主义和“一刀切”，根据实际情况和法律精神因地制宜地执法；提高执法的精度和力度，对于食品浪费严重的现象进行严惩。
三、反食品浪费引导商家自律。建立自律监督机制，企业和商家自查自纠，发现食品浪费问题及时整改；同时需要保证食材的新鲜和安全，针对不太好看但还能吃的食材，可以员工内部消化，或定向捐给一些社会组织，做到物尽其用。
四、反食品浪费引导市民监督。将开通多元的举报渠道，例如市长信箱等，鼓励市民对于食品浪费问题进行举报。
反食品浪费是一场“持久战”，作为市场监管局，针对食品浪费问题，我们会做好本职工作，不断地完善法律法规，加强执法。同样我们也希望社会各界与我们共同努力，提高全民节约粮食的意识，形成勤俭节约的社会风气。
G市市场监管局
XXXX年XX月XX日');
INSERT INTO shenlun_paper (id, paper_code, title, year, version, question_count) VALUES (2, '2007-fy', '2007年国家公务员考试《申论》真题', 2007, '副省级', 5);
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 1, '材料1', '1、河北省会石家庄市西北的北焦村，是市二环路内45个城中村之一，1200多户、3000多人，一些外地人在村里租房做生意，多数村民靠收房租生活。
1968年2月。河北省会从保定迁至石家庄，失去迅猛扩张，近郊土地被征用的速度急剧加快，修铁路，该生活区，建机关，猖狂，医院，学校。都在征地。71岁的原村支书陈某说：当地土地征用，政府不给钱，但一亩地拔2—3个民名额给村民身份由农民转为工人，改革开放以后，国家征地越来越多。省政府的外贸、内贸、轻工业和化工等七个厅局级机关先后来到北焦村扎寨。村中布满机关宿舍。北焦村因此号称七局宿舍。
1975年，陈某还是生产大队长，他记得70年代开始国家征地油料补贴。这些补贴主要归生产大队，用于发展集体企业，村民进企业坐丁，北焦村靠土地补贴该岂料旅馆、商店，办起了塑料厂、鞋厂等20多家企业。
当时国家规定土地按征用前三年平均产值来补偿，补偿分为土地补贴，劳动力补贴和青苗补贴三种，1971年，1亩地补贴240元；1976年，每年1亩补贴1000元。陈某说，补贴增加是因为村民改种粮食为种蔬菜，土地产值增加了。
1986年陈卸任时，北焦村还剩下三四目的。之后，北焦村剩余农地陆续征用，目前只有30多亩自留地，供村民终点菜，但多半荒草丛生。
《财经时报》2004年报道，中国过去10年间转眼让土地达一亿亩。《中国改革》杂志2004年引用一项条查表明。被征用土地的收益分配大致是：地方政府占20%—30%，企业40%—50%，村级组织25%—30%。农民仅占5%—10%地方政府采取强制性土地征用政策。被媒体大力地宣传。在商业利益和政府双重利益的驱动下，城郊农民大量失地，而不法之徒也由此以权力寻租的方式。
从北焦村乘车行驶不到半小时，可到达西营村。西营村处在石家庄市城市地下水源一级保护区内。工厂不让进，企业也不让进。但2002年8月经省里特批河北政法职业薛原准备在石家庄市北郊征用土地新建校区。
西营村村委会主任杨某说，当时为了争夺学校进村，其他村都相互压价，贱卖土地。最后，学员倾向于在西营村征地920亩。2003年西营村党支部和村委会决定对学院争第一是进行民意测验，89%的村民同意征地，11%的村民不同意征地。村党支部和村委会据此成立谈判小组，与学院正式谈判。双方达成的结果时，学院为每亩地支付征地补偿费7万元，还有其他补偿。
但在2004年4月一份集体上访的材料上，至少有360多名村民签字画押反对上述征地方案。西营村现有村民2000人左右，反对者占18%以上。按《村委会组织法》的规定，涉及村民利益的重大事项，村委会必须提请村民会议讨论决定，方可办理；又十分之一以上的村民提议，也应当召集村民会议。
该建设被确定为河北省2004年重点建设项目。3月，省国土资源厅和石家庄市政府同意该项目进行工程用地的前期准备工作。但为平整土地，学院和村委会跟村民多次发生冲突。结果时，学院派施工人员用履带拖拉机将土地推平，村委会派人把耕地下面用来灌溉的地下水道挖断，致使大部分耕地闲置至今。学院原定2004年9月新生入住新校区，而到了11月，还为破土动工。
眼球着是几亩的果树一颗一颗干死，村民高某很心疼。100多亩蔬菜大棚，菜秧都长出一寸了，他们说拆就拆。村民傅某说，一家5口共有5亩地，其中2.7亩被征用。他说，2.7亩地若种小麦和玉米，年收入由两千来元，种蔬菜年收入也有两三千元。5亩地一年收入一万来元，勉强够全家一年的开销。他说，家里的粮食，两个小孩上学，日常花费，都是从地里处。村里的一个企业也没着落。
据村委会主任杨某介绍，到10月，学院仅付款2350万元，只占总额的三分之一多。其中，2000万元平均分给2000多个村民，每人1万元，剩下300万元先由村委会保管。杨说，等省国土厅发布公告，征地款才能全部到帐，到帐后也将全部分给村民。现在村里欠每个村民2万元。
1998年修订的《土地管理法》规定，征用耕地的补偿费用包括土地的补偿费、安置补助费以及地上附着物和青苗的补偿费。土地补偿费，为该耕地被征用前3年平均年产值的6至十倍。安置补助费，按照需要安置的农业人口数计算，每人的补助标准为该耕地被征用前3年平均年产值的4至6倍。按照这个标准的最高倍数乘以2000元的亩产值，西营村村民每亩地最多获得土地补偿费2万元，安置补偿费1.2万元，总计3.2万元。
《土地管理法》还规定，依照上述规定支付土地补偿费和安置补助费，尚不能是需要安置的农民保持原有生活水平的，经省、自治区、直辖市人民政府批准，可以增加安置补助费。但是，土地补偿费和安置补助费的总和不得超过土地被征用前三年平均产值的30倍，则西营村村民每亩地最多可获得6万元补偿费。
如此计算，政法职业技术学院向西营村支付征地补偿费每亩7万元，似乎村民已经占了便宜。2003年4月，石家庄市政府公布了市区土地基准地价，将商业用地分为八集，以及每平方米为4723元，折合每亩94万多元；8级每平方米为497元，折合每亩9.9万多元。这意味着，西营村被征用土地所获得的补偿，比用于商业开发，每亩最低少2.9万元，最高少87万元。西营村部分村民一直想按照商业用地的市场价出让土地。但政法职业学院建新校区不属于商业用途，村民的愿望在现行法律和法规中找不到依据。事实上，村民没有权利为自己的土地定价。
西营村的情形在中国农村非常普遍。据社科院农村发展研究所提供的数据，从1990年到2002年，全国占用耕地4736万亩用于非农建设，今后每年非农建设用地仍需要250万-300万亩。这些非农建设用地主要集中在城郊农村，那里一般人均耕地不足0.7亩。每占用一亩耕地就会造成1.4人失去土地，依此推算，13年来至少有6630万农民失去了土地。
专家认为，由于征地补偿标准低，失地农民所获得的补偿不足以创业，政府又没有为他们建立合理的安置和社会保障制度。这些失地农民大都成了无地可种、无正式工作岗位、无社会保障的流民。而中国历史上的社会动荡，流民都成为隐患。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 2, '材料2', '2、北焦村的土地所剩无几，村办企业在20世纪90年代中期也相继破产。从2000年起，北焦村就陆续有村民上访，开始六七人，到现在已有几百人集体上访，累计上访1000多人次。石家庄长安区南高营镇西古城村，有关部门为搞土地开发，造成380亩耕地、菜地无法耕种，至今垃圾成堆，杂草丛生，已闲置了四年。村民上访无效后，自发组织起来，在耕种地旁搭了间瓦房，日夜轮流看守，反对圈占。
《土地管理法》规定，国家为了公共利益的需要，可以依法对集体土地实行征用。但大量营利性商业项目，都以公共利益的名义强制征用土地，从而引发农民的群体性上访和干群冲突。调查显示，农村土地纠纷已经取代税费争议而成为目前农民维权的焦点，严重影响农村的社会稳定和发展。一家长期研究农村问题的学术机构收集到2004年来发生的130起农村群体性突发事件，其中87起因土地问题印发，造成数百农民受伤，3人死亡。专家认为，土地是农民生存保障，土地涉及巨额的经济利益，这就决定了土地争议具有对抗性和持久性的特征。
某研究农村经济问题的专家提出，农村城市化进程可以有两种选择，一种是将原有的集体经济组织全部解散，农民以独立的家庭文字个体进入城市经商、打工，但前提是必须实现公平分配，另一种保留原有的农村社区组织，并对产权制度和组织形成进行彻底改造，以适应城市化的进程。2004年10月底，国务院下发了《关于深化改革严格土地管理的决定》，强调农用地转用和土地征收的审批权在国务院和省、自治区、直辖市政府，各省、自治区、直辖市政府不得违反法律和行政法规的规定下放土地审批权。该《决定》对农民最关注的征地补偿作了新承诺；土地补偿费和安置补助费的总和达到法定上限，尚不足以使被征地农民保持原有生活水平的，当地政府可以用国有土地有偿使用收入予以补贴。县级以上政府应当使被征地农民的长远生计有保障。这意味着各级政府要将土地出让金部分转移给被征地的农民。
部分媒体称这个决定是土地新政，并给予较高评价。但部分上访农民则有更高的期待。福建厦门市海沧区霞阳村的许说，村里的3000多亩地都被征光了，他希望中央政府真正给农民土地所有权和使用权。政府要保障农民的经济权利，为农村经济发展服务，不要与农民争利，更不能把农民的土地抢走给开发商，他期望征地制度改革能让农民拿自己的土地直接进入市场交易，有的专家，倾向于根据土地使用性质，把土地转让市场区分为两大类进行交易，以保障农民得到应有的补偿。这位专家还指出，目前存在两级市场，政府对一级市场具有垄断权，土地交易先由国家或集体收回，再进入二级市场交易转，这导致转让利益分配严重不均。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 3, '材料3', '3、以占江苏不足4.7%的面积，承载了江苏6.2%的人口，产出了占江苏14.8%的经济总量，以保护土地资源来保障发展，以保障经济发展促进资源保护，成为写在无锡大地上的辩证法，据统计，江苏全省GDP每增一个百分点，用地量为2.4万亩。2003年，无锡GDP实现1901.22亿元，增幅达15.4%，而用地增加仅15.6万亩，土地资源消耗量仅相当于全省平均水平的一半。
在无锡4787.6平方公里的总面积中，山丘与水域占47.7%，人均耕地仅0.55亩，为江苏地级市中最少的城市。但随着经济社会的迅猛发展，无锡对土地的需求量很大。无锡市政府用严格的制度保护耕地，耕地占一补一的工作列入各级政府年度考核目标，每年以“市长令”形式下发土地复垦方法，全面开展土地开发整理，明确“谁开垦谁受益”。连续多年来，无锡每年都召开土地复垦流动现场会，极大激发了基层热情。宜兴原茗岭镇是人均粮田而且增加耕地3400多亩，这里实施的国家级“丘陵山区万亩土地综合开发整理项目”，被联合国列为在我国的11个师范区之一。2001年至今，无锡关闭了沿太湖地区200多家矿山企业，通过土地开发整理，共新增耕地4.3万亩，相当于10余个中心商务区。目前，正在建造28层高的农民公寓。据测算，原来农民散居时户均占地超过0.5亩，住进户公寓后户均占地不足0.15亩。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 4, '材料4', '4、首钢矿业公司在各级政府部门的指导下，加大投入，加强管理，技术创新，先后完成了大石河铁矿尾矿库，新水选矿厂尾矿库，裴庄土场，羊崖山土场等一大批复垦项目，使矿山的生态环境得到了初步的改善。经多年覆土植被，大石河铁矿尾矿库，如今处处郁郁葱葱，长满了紫穗槐，三四年前还是一座沙山的新水尾矿库，如今1200余亩沙棘长势旺盛，已结出沙棘果；裴庄土场覆土种植的刺槐已经成长为一片参天大树，好像一座森林公园。
首钢矿业公司在生产过程中破坏土地，主要是采矿中形成排土场和在选矿中形成尾矿库，针对不同的条件，公司组织工程技术人员进行攻关，采取不同方式开展土地复垦工作。
排土场是采矿过程中排出的岩石，堆存场所，是人工堆积起来的废石山，岩石裸露，陡坡较陡。公司对排土场采取了平整、覆土、绿化的办法。一是在采矿过程中，将采矿剥离后表土单独存放，以备复垦利用。二是待排土场停用后，用推土机平整，为减少工作量，做到小平大不平，平台四周做出0.5米的土挡，防止水土流失。三是将存放的表土覆在上部，厚度0.5米，栽种以刺槐，紫穗槐为主的水土水土保持林。首钢采用此方法先后使2950亩排土场披上了绿装。
首钢公司目前有尾矿库3座，尹庄尾矿库是1996年投入使用的新库，不具备复垦条件，另外2座尾矿均已进行了复垦。为防止水土流失，首钢公司每年投入大量资金沿坝面堆成10-15米平台，砌有排水沟，保证了汛期雨水沿排水沟排走，从而防止了水土流失。在平台和平台后斜坡上覆盖20厘米厚的土，种植以紫穗槐为主的坝面水土保持林。经过几年的实践，已完成尾矿坝绿化600余亩，给库区周围的群众建起一条绿色防护带，有效地控制了二次扬尘污染，也为我国固体废物治理探索出一条新的路子。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 5, '材料5', '5、从2004年起，河南省开展了整治了“空心村”、砖瓦窑场和工矿废弃地的工作，计划用5年整治出土地150万亩，用于县城经济发展用地或重新恢复为耕地。截至目前，整治出土地46万亩，净增耕地总量26万亩。全省已连续6年实现耕地占补平衡。
不久前，郸城县王拱集村的李老汉得到了一份“大礼”，他家从村里多分了两亩地。“空心村”整治后，该县许多农民都像李老汉一样享受着这份喜悦。目前，郸城县已完成了19个“空心村”的智力，新增耕地7801.7亩。河南省国土资源部门有关负责人介绍，该省人均耕地只有1.23亩，低于全国平均水平。而全省从“空心村”、砖瓦窑场和工矿废弃地整治中可挖掘出土地223.4亩，可复垦耕地183.3万亩。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 6, '材料6', '6、现实的土地供应中到底存在不存在“地荒”？某专家的回答是否定的。他认为，在城市特别是大型城市，仍要提供土地，支持中小户型，支持中小户型、中低价位商品住房的建设用地需求，要严格控制大户型和低密度的住房建设，坚决停止别墅建设。
记者了解到，“长三角”地区的用地虽然非常紧张，但是仍然有很大的潜力。这种潜力主要来自与城乡之间的统筹，来自于土地的再利用和再调整。通过存量土地的调整和再调整，旧城旧村，老工业区和老企业改造，可以在已有土地中腾出新的用地空间，能在不占或少占耕地，控制新增建设用地总量的前提下，实现经济和社会持续健康发展。
据悉，近几年来，我国房地产业用地占了全国供地总量的30％左右。一边是建设用地的追加，一边是开发商叫喊“地荒”。问题在哪里？闲置问题实在是“地荒”的一个顽疾。
2001年以来。江苏省苏州市区以法取消了184个项目，收回土地达6760亩。仅2005年，苏州市盘活存量土地2505宗，占建设用地面积的35.7%。
一位业内人士说，大量的土地闲置，主要是因为一些地方不按经济规律办事，盲目铺摊子、上项目、大面积占用土地。同时土地管理措施不力，为一些地方变相非法批地、盲目征用或出让土地带来了可乘之机。当然，城乡规划之中的粗放用地也“消耗了”大量建设用指标。
按照国家关于城市规划建设用地的最高定额，一般城市人均用地面积最高标准是100平方米，首都和特区城市最多是120平方米。但有关部门统计，我国664个城市中，城镇居民人均用地已达到133平方米，而世界上发达国家人均城市用地是82.4平方米，发展中国家人均城市用地是83.3平方米。
有关部门负责人认为，必须严格控制建设用地的规模，今后土地利用必须保证60%以下是存量土地。据了解60%的提法是新的表述，以前的表述是要求地方充分利用现有建设用地，不占或少占农民用地，而没有量化标准。');
INSERT INTO shenlun_material (paper_id, m_no, title, content) VALUES (2, 7, '材料7', '7、在许多国家或者说在全球范围内，如何有效地利用和保护土地资源对正在增长的千千万万人民来说，是生死攸关的问题。更大数目的下代人正处在更严重的危险境地，即目前的生产正在毁坏将来农业赖以生存的土地资源。为了满足日益增长的需求，全球的农业生产必须大幅度地增长，而对具体的每一地方来说，当务之急是保护农业生产的基础—土地资源。应为，全球所有类型的食物的98%是在陆地上生产的，海洋和陆地水域的产量不到2%。植物产品构成了人类膳食的92%，占全世界膳食供给量的8%的动物产品也间接地来自于生长在陆地上的植物。也就是说，要保持农业产品或农业生产的持续增长，必须保持土地利用的持续性，凡谷底资源退化和不断提高土地质量或生成潜力。土地利用方式和农业生产措施在很大程度上控制着土地退化过程也决定着土地利用的持续性。
农业生产是一个开放系统，受到各种各样的自然环境条件的影响和限制。将集约农业方式转移到贫穷的农民所居住的边际，和近边际地区，经常导致土地退化和生态灾难。因此，不能无限制地开发利用土地，有些土地必须保护起来。
施肥、灌溉和其他投入，可以继续获得可观的成功。但生态环境成本将越来越高。如目前化肥投入区，一经发现了地下水硝酸盐富集现象，长期使用农药，使病虫产生了抗性，也污染了环境。如进一部加大化肥和农药的投入，不但经济效益下降，而且会造成土壤和地下水的污染。因此人们正在探讨既能继续增产，又不破坏水土资源环境的持续土地利用管理方法，防止土壤与水质退化就是维护土地资源的质量和生产能力。因此，有必要就持续土地利用管理制定评价标准，用来检验和检测土地开发，利用是否是持续的。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (2, 1, '一、根据“给定材料1、2”的内容，整理一份供有关负责同志参阅的材料。
要求：概述全面，观点鲜明，条理清楚，语言流畅，不超过500字。', 30, 500, '近几年来，在工业化、城镇建设进程不断加快的新形势下，大量农村集体用地被国家征用。
就以河北北焦村和西营村为例，当地的土地征用基本情况为：第一，耕地流失严重。第二，土地征用的补偿费用偏低，无法弥补农民的损失。第三，在土地征用的过程中存在违法违规的操作行为。第四，利益的冲突无法很好地解决导致了上访现象的增加。
由上述情况我们可以发现，我国在城市化发展取得巨大成就的同时，在农村土地征用问题的许多方面仍略显不足。首先，部分地区的征用土地的利用效率偏低，存在部分征地处于荒废状态的现象。其次，从经济学角度来衡量，征地收入与征地赔偿之间存在不等价性，在获得巨大征地收入的前提下，对失地农民的补偿费用过低，这是违反价值规律的经济行为。再次，从构建和谐社会的角度看，农民的权益没有得到完全的维护必然会影响社会的稳定。第四，农村的一些相关管理部门存在违法违规卖地的行为，如贱卖土地、拖欠农民土地补偿费等问题。第五，从市场经济的角度来看，作为土地使用权的“卖方”的农民，却没有权利为自己的土地使用权定价，这也是不符合市场经济规律的。
我国政府针对这个问题，已出台《关于深化改革严格土地管理的决定》，规范审批权，相信该社会问题将逐步地得到解决。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (2, 2, '二、“给定资料7”提出了“持续土地利用管理”的问题。请结合“给定材料3—7”，谈谈对“持续土地利用管理”应从哪些方面评价。
要求：分条作答，简明扼要，不超过200字。', 15, 200, '应从土地使用效率和土地的可持续利用两方面来评价。
从土地使用效率看：（一）建设用地的规模（二）人均用地量（三）经济产出与用地的比例关系（四）闲置土地的有效利用（五）建设用地规模的控制（六）土地复垦的效果
从土地的可持续利用看：（一）防止土地资源退化，提高土地质量（二）适度地开发土地（三）植树造林，防止水土流失（四）增加对荒地的使用，减少对耕地和森林资源的使用（五）适度的施肥、灌溉，保护生态环境');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (2, 3, '三、本题仅限报考行政执法类、市（地）以下综合管理类职位的考生作答。
1、给定材料中谈到了排土场、尾矿库的绿化，“空心村”、砖瓦窑场和工矿废弃地的整治，请概括说明这些做法的目的和意义。不超过200字。（10分）
2、根据“给定资料6”，试分别解释“存量土地”和“地荒”的含义。（15分）', 25, 400, '1、目的：一、加快复垦速度，提高废弃用地的使用率。二、绿化整治可以防止水土流失，改善生态环境。三、通过整治可以增加耕地面积，实现耕地占补平衡，同时可使农民获得实惠。四、绿化还可以控制扬尘污染，保护环境。
意义：通过这些措施促进了土地的合理使用，有利于环境保护，同时也改善了周边农民的生活。
2、存量土地：城市建设“存量土地”是指现有城市建设用地，特指现有城市建设用地中的低效利用的、破产企业闲置的建设土地、需要调整的不符合城市规划的其他建设土地，通过收购、收回方式将这部分土地储备起来，而后依照规划进行招拍挂方式出让。
地荒：是指城市建设用地的供应量不能满足实际需求的问题。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (2, 4, '四、本题仅限报考省级（含副省级）以上综合管理类职位的考生作答。
1、“给定资料2”提到“把土地转让市场区分为两大类进行交易”，请进一步说明这两大类市场怎样区分，并谈谈在这两大类市场中怎样解决“农民没有权利为自己的土地定价”的问题。不超过200字。（10分）
2、假如中央有关部门成立联合检查组，对地方征用农民集体所有土地补偿费管理使用情况进行专项检查，请列出此项检查所查的主要内容。（15分）', 25, 400, '1、两大类市场的主体不同：一类市场的主体是政府和农民，政府是买方，农民是卖方，标的物是土地的使用权，这是农民出让土地使用权的过程；另一类市场的主体是政府和土地的开发商或投资者，政府是卖方，这是政府转让土地使用权的过程。
解决“农民没有权利为自己的土地定价”问题：要完善社会主义市场经济制度，政府要转变角色，从“主导”逐步过渡到“引导”；完善相关的征地制度，平衡每一方的利益要求；完善相关的补偿制度，不仅要补偿农民个人，也要补偿农民所在的农村集体组织，更要补偿当地的环境。
2、检查主要内容：一、审核征地的面积，看当地的征地行为是否合理合法。二、根据当地的经济水平，以确定征地的价格是否合理。三、根据被征地农民近三年平均产值，以及征地后的农民实际产值，以确定土地补偿费的使用能否弥补征地后农民的生活需要。四、审核土地的出售价格，核算后以确定土地补偿费的额度是否合理。五、审核征用地所兴建的项目，以确定是否符合当地经济发展的需要，是否符合环保和可持续发展的要求。');
INSERT INTO shenlun_question (paper_id, qno, title, score, word_limit, ref_answer) VALUES (2, 5, '五、请以“命脉”为题，写一篇关于土地问题的文章。
要求：1、参考给定资料，自选角度，提出问题，解决问题。2、观点明确，联系实际，分析具体，条理清楚，语言流畅。3、全文不少于800字。', 30, 800, '命脉——“把脉”中国的土地问题
西汉的贾谊有句话，说明了当时土地与人民的关系。“富者田连阡陌，贫者无立锥之地”。可见对于人民来说，自古以来土地就是人民的命脉。而到了现代社会，土地仍然也是农民的命脉。目前，随着工业经济不断发展，城市快速扩大化的冲击，农民对土地固有的使用权在发生着各种各样的变化，在这个变化过程中，农村土地征用过程中存在的问题尤其突出。
在城市先进经济主导整体经济的时代，农村地域缩小、人口减少是必然趋势，国家的作用在于在这个城乡变迁过程最大限度地捍卫和保护农民的利益，以实现工业经济快速发展、农民利益不受损的双赢局面。那么我们应该怎样达到这种双赢的局面呢？笔者认为应从以下几个角度来考虑：
从经济学的角度看，最大的问题在于目前我国的征地赔偿与征地收益之间存在巨大的差额。这首先就不符合价值规律的原则，因为征地赔偿实际就是农民土地使用权的“价格”，而征地收益更多的是体现农民土地使用权的“价值”。我们要重拾价值规律的精神和原则，制定合理的有弹性的符合当地经济发展水平的征地赔偿制度，切实维护被征地农民的合法权益，进一步完善征地程序，建立补偿标准听证制度，严格按法律规定落实补偿安置措施，严厉查处拖欠、挪用、截留土地补偿费等违法行为。
从社会学的角度看，农村土地征用过程中存在的问题直接影响了农民的实际利益，引起了部分被征地农民的不满，导致了一些冲突、上访等不和谐的社会现象。政府需要做更多的协调、引导工作：完善相关的土地征用和管理的制度；解决农民在失地后的“谋生问题”，积极探索解决被征地农民社会保障和长远生计的有效办法，建议设立失地农民社会保障基金；建立健全农村劳动力的培训机制，拓宽农民增收渠道。
从环境保护的角度看，要认识到土地资源的合理利用是关系到子孙后代福祉的大事。关键在于“监督”和“教育”。从我国国情出发，实行最严格的耕地保护制度，尤其是要重点保护基本农田，同时还要做好土地占补平衡工作，充分挖掘土地资源潜力，以促进土地资源可持续利用，保障国家粮食安全。
通过以上几个角度的分析，我们可以看到，土地实际上不仅仅是农民的命脉，也是城市居民，甚至是我们整个国家的命脉所在。我们要为这个社会问题好好地把把脉，找到问题的症结所在，然后对症下药，自然就能药到病除了。');